def caesar(s, k):
    result = []
    for char in s:
        if char.isalpha():
            base = ord('a') if char.islower() else ord('A')
            shifted = (ord(char) - base + k) % 26
            if shifted < 0:
                shifted += 26
            result.append(chr(base + shifted))
        else:
            result.append(char)
    return ''.join(result)

def caesar(s, k):
    result = []
    for char in s:
        if char.islower():
            base = ord('a')
            shifted = (ord(char) - base + k) % 26
            result.append(chr(base + shifted))
        elif char.isupper():
            base = ord('A')
